from mk import *
def P(*ps): return ''.join(f'<p>{p}</p>' for p in ps)
Q=[]
def add(n,t,o=None): Q.append((n,t.replace('\n',' '),o))
add(1990,r"For the function $f$, for each increase in the value of $x$ by $c$, where $c$ is a positive constant, the value of $f(x)$ increases by a factor of 16. Which of the following equivalent forms of the function $f$ displays $\frac{1}{c}$ as a coefficient of $x$?",
 r"$f(x)=139\left(16^{\frac{1}{3}}\right)^{\frac{1}{2}x}$ | $f(x)=139(8)^{2x}$ | $f(x)=139\left(8^2\right)^{\frac{1}{2}x}$ | $f(x)=139\left(64^{\frac{2}{3}}\right)^{\frac{1}{8}x}$")
add(2024,P("An acceptable noise criterion rating for the background noise in a school classroom is 30. For a noise criterion rating of 30, the equation")+S(r"y=19(0.978)^{x-50}+37")+P(r"gives the estimated sound pressure level, $y$ in decibels, as a function of the octave band center frequency, $x$, in hertz, where $x\ge 50$. Which of the following is the best interpretation of 37 in this context?"),
 "37 is 19 less than the estimated sound pressure level, in decibels, at an octave band frequency of 50 | 37 is 19 less than the estimated sound pressure level, in decibels, at an octave band frequency of 0 | 37 is the estimated sound pressure level, in decibels, at an octave band frequency of 50 | 37 is the estimated sound pressure level, in decibels, at an octave band frequency of 0")
add(2031,r"At different times on a certain day, a manager at a theme park recorded the number of visitors. An exponential model gives the estimated number of visitors, $V$, at the theme park $t$ hours after the theme park opened, where $t\le 3$. Based on the model, 85 visitors were estimated to be at the theme park when it opened, and every 30 minutes the estimated number of visitors increased by 140% of the estimated number of visitors 30 minutes earlier. Which of the following equations best represents this model?",
 r"$V=85(1.40)^{\frac{t}{30}}$ | $V=85(1.40)^{2t}$ | $V=85(2.40)^{\frac{t}{30}}$ | $V=85(2.40)^{2t}$")
add(2285,r"A beekeeper's initial observation of the population of a certain bee colony was 1,600 bees. The beekeeper set a goal to increase the population to 2,975 bees. The beekeeper uses a model that predicts the population of this bee colony begins at 1,600 and increases by 110 bees per week in the first two weeks after the initial observation, and then increases by 165 bees per week until the beekeeper's goal is reached. According to this model, at the end of week $w$ after the initial observation, where $w\gt 2$, which of the following functions gives the predicted number of bees still needed to reach the beekeeper's goal?",
 r"$p(w)=-110+165w$ | $p(w)=1{,}485-165w$ | $p(w)=2{,}865+165w$ | $p(w)=2{,}975-165w$")
add(2300,tbl(['','1','2','3','4','5','Total'],[['Adults','13','35','103','82','17','250'],['Children','6','22','27','70','25','150'],['Total','19','57','130','152','42','400']],'Ratings Given to a Movie on Release Night')+P("On the first night of each movie's release, the manager of a movie theater asks the people who saw the movie to rate it on a scale of 1 (worst) to 5 (best). The table above summarizes the responses of all 400 viewers of one particular movie.","How does the median rating of the adults who saw the movie compare to the median rating of the children who saw the movie?"),
 "The median ratings are the same. | The median rating of the adults is greater. | The median rating of the children is greater. | The table does not give enough information to compare the medians.")
add(2434,tbl(['Pieces of mail','Days'],[['0','2'],['3','2'],['4','2'],['5','2'],['6','1'],['7','1'],['18','1']])+P("The data value 18 is removed from data set A to create data set B, which consists of the remaining 10 data values. Which statement best compares the median of data set A and the median of data set B?"),
 "The median of data set B is less than the median of data set A. | The median of data set B is greater than the median of data set A. | The median of data set B is equal to the median of data set A. | There is not enough information to compare the medians of the two data sets.")
add(2732,r"Trapezoid $CDEF$ is similar to trapezoid $JKLM$, such that $C$, $D$, $E$, and $F$ correspond to $J$, $K$, $L$, and $M$, respectively. The length of each side of trapezoid $JKLM$ is 3 times the length of its corresponding side in trapezoid $CDEF$. The measure of angle $C$ is $42^\circ$. What is the measure of angle $J$?",
 r"$39^\circ$ | $42^\circ$ | $45^\circ$ | $126^\circ$")
